import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"58、【兑】 兑下兑上","description":"横渠易说 - 58、【兑】 兑下兑上","frontmatter":{"title":"58、【兑】 兑下兑上","description":"横渠易说 - 58、【兑】 兑下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/060.md","filePath":"zh/classics/hengqu/060.md"}'),l={name:"zh/classics/hengqu/060.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_58、【兑】-兑下兑上" tabindex="-1">58、【兑】 兑下兑上 <a class="header-anchor" href="#_58、【兑】-兑下兑上" aria-label="Permalink to “58、【兑】 兑下兑上”">​</a></h1><h3 id="彖曰-兑-说也-刚中而柔外-说以利贞-是以顺乎天而应乎人。说以先民-民忘其劳-说以犯难-民忘其死。说之大-民劝矣哉" tabindex="-1">彖曰：兑，说也，刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉! <a class="header-anchor" href="#彖曰-兑-说也-刚中而柔外-说以利贞-是以顺乎天而应乎人。说以先民-民忘其劳-说以犯难-民忘其死。说之大-民劝矣哉" aria-label="Permalink to “彖曰：兑，说也，刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉!”">​</a></h3><h3 id="象曰-丽泽兑-君子以朋友讲习。" tabindex="-1">象曰：丽泽兑，君子以朋友讲习。 <a class="header-anchor" href="#象曰-丽泽兑-君子以朋友讲习。" aria-label="Permalink to “象曰：丽泽兑，君子以朋友讲习。”">​</a></h3><h3 id="初九-和兑-吉。-象曰-和兑之吉-行未疑也。" tabindex="-1">初九，和兑，吉。 象曰：和兑之吉，行未疑也。 <a class="header-anchor" href="#初九-和兑-吉。-象曰-和兑之吉-行未疑也。" aria-label="Permalink to “初九，和兑，吉。 象曰：和兑之吉，行未疑也。”">​</a></h3><p>以阳居下，无所比附，出门同人，行自信者也。</p><h3 id="九二-孚兑-吉-悔亡。-象曰-孚兑之吉-信志也。" tabindex="-1">九二，孚兑，吉，悔亡。 象曰：孚兑之吉，信志也。 <a class="header-anchor" href="#九二-孚兑-吉-悔亡。-象曰-孚兑之吉-信志也。" aria-label="Permalink to “九二，孚兑，吉，悔亡。 象曰：孚兑之吉，信志也。”">​</a></h3><p>私系于近，悔也。诚于接物，信而不妄，吉且悔亡。</p><h3 id="六三-来兑-凶。-象曰-来兑之凶-位不当也。" tabindex="-1">六三，来兑，凶。 象曰：来兑之凶，位不当也。 <a class="header-anchor" href="#六三-来兑-凶。-象曰-来兑之凶-位不当也。" aria-label="Permalink to “六三，来兑，凶。 象曰：来兑之凶，位不当也。”">​</a></h3><h3 id="九四-商兑未宁-介疾有喜。-象曰-九四之喜-有庆也。" tabindex="-1">九四，商兑未宁，介疾有喜。 象曰：九四之喜，有庆也。 <a class="header-anchor" href="#九四-商兑未宁-介疾有喜。-象曰-九四之喜-有庆也。" aria-label="Permalink to “九四，商兑未宁，介疾有喜。 象曰：九四之喜，有庆也。”">​</a></h3><p>通其邪佞，使进而上，则小人道长而不宁，以谄为疾而拒外之，则终不失其得偶之庆也。</p><h3 id="九五-孚于剥-有厉。-象曰-孚于剥-位正当也。" tabindex="-1">九五，孚于剥，有厉。 象曰：“孚于剥”，位正当也。 <a class="header-anchor" href="#九五-孚于剥-有厉。-象曰-孚于剥-位正当也。" aria-label="Permalink to “九五，孚于剥，有厉。 象曰：“孚于剥”，位正当也。”">​</a></h3><p>说六三之进，则是孚于剥，近危之道也。故处乎盛位者，佞不可亲也，当正位而进小人，信乎剥之道也。</p><h3 id="上六-引兑。-象曰-上六引兑-未光也。" tabindex="-1">上六，引兑。 象曰：“上六引兑”，未光也。 <a class="header-anchor" href="#上六-引兑。-象曰-上六引兑-未光也。" aria-label="Permalink to “上六，引兑。 象曰：“上六引兑”，未光也。”">​</a></h3><p>与三为类而引升之，虽不伤类，然未足多也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
